// Collect NSE session cookies from the first call and fan out to the two indices.
const sc = $input.first().json.headers?.['set-cookie'] || [];
const cookie = (Array.isArray(sc) ? sc : [sc]).map(c => c.split(';')[0]).join('; ');
// Add/remove NSE index symbols here (e.g. 'FINNIFTY', 'MIDCPNIFTY').
return ['NIFTY', 'BANKNIFTY'].map(symbol => ({ json: { symbol, cookie } }));

const symbols = $('Prepare Requests').all().map(i => i.json.symbol);
const chains  = $('NSE Option Chain').all().map(i => i.json);
const fmt = n => Number(n).toLocaleString('en-IN');
const sgn = n => (n > 0 ? '+' : '') + fmt(n);
const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
const out = [`📊 <b>India Market Update</b> — ${now} IST`];

chains.forEach((c, i) => {
  const name = symbols[i];
  const rec = c && c.records;
  if (!rec || !rec.data || !rec.data.length) {
    out.push(`\n<b>${name}</b>: NSE data unavailable (request blocked or session expired)`);
    return;
  }
  const expiry = rec.expiryDates[0];                       // nearest expiry
  const rows = rec.data.filter(r => r.expiryDate === expiry);
  let ceOI = 0, peOI = 0, ceChg = 0, peChg = 0;
  let maxCE = { oi: 0, strike: 0 }, maxPE = { oi: 0, strike: 0 };
  for (const r of rows) {
    if (r.CE) {
      ceOI += r.CE.openInterest || 0; ceChg += r.CE.changeinOpenInterest || 0;
      if ((r.CE.openInterest || 0) > maxCE.oi) maxCE = { oi: r.CE.openInterest, strike: r.strikePrice };
    }
    if (r.PE) {
      peOI += r.PE.openInterest || 0; peChg += r.PE.changeinOpenInterest || 0;
      if ((r.PE.openInterest || 0) > maxPE.oi) maxPE = { oi: r.PE.openInterest, strike: r.strikePrice };
    }
  }
  const pcr = ceOI ? (peOI / ceOI).toFixed(2) : 'n/a';
  out.push(
`\n<b>${name}</b>  ${fmt(rec.underlyingValue)}  (expiry ${expiry})
Call OI ${fmt(ceOI)} (${sgn(ceChg)}) | Put OI ${fmt(peOI)} (${sgn(peChg)})
PCR ${pcr} | Max Call OI (resistance) ${maxCE.strike} | Max Put OI (support) ${maxPE.strike}`);
});

// Sensex: index level only (BSE has no free public OI feed)
const m = $input.first().json?.chart?.result?.[0]?.meta;
if (m && m.regularMarketPrice) {
  const prev = m.chartPreviousClose ?? m.previousClose;
  const ch = prev ? m.regularMarketPrice - prev : 0;
  const pct = prev ? (ch / prev * 100).toFixed(2) : '0.00';
  out.push(`\n<b>SENSEX</b>  ${fmt(m.regularMarketPrice)}  (${ch >= 0 ? '+' : ''}${ch.toFixed(2)}, ${pct}%)\nOI: not available from a free public source`);
} else {
  out.push(`\n<b>SENSEX</b>: quote unavailable`);
}
return [{ json: { text: out.join('\n') } }];
